var b="url",c="01__lpصفحه_اصلی_کارشناس_حقوقی_وکیل_.html",d="generationDate",e=new Date(1762055282875.19),f="defaultAdaptiveView",g="name",h="Large Display",i="size",j="width",k=1200,l="height",m=0,n="adaptiveViews",o="sketchKeys",p="",q="s0",r="variables",s="OnLoadVariable",t="vas",u="vas2",v="vijadparvande",w="baz",x="nn",y="ne",z="neg",A="mo",B="ve",C="f",D="vparvandeha",E="h1",F="h2",G="vetelatpaye",H="vamalyatparvande",I="v",J="passf",K="loginv",L="op1",M="op2",N="op3",O="op4",P="op5",Q="op6",R="op7",S="statehoghoghi",T="statehoghoghiazparvandeha",U="vdarkhastha",V="page",W="packageId",X="286db31237474521a4fcb4397af2ddbb",Y="type",Z="Axure:Page",ba="01. LPصفحه اصلی(کارشناس حقوقی/وکیل)",bb="notes",bc="annotations",bd="fn",be="1",bf="ownerId",bg="6fd63c7469b94c4d84310a53b63c5a17",bh="label",bi="(Text Field)",bj="Note",bk="<p><span style=\"font-family:'Yekan Bakh FaNum Bold', 'Yekan Bakh FaNum Regular', 'Yekan Bakh FaNum', sans-serif;font-weight:700;\">بر اساس زمان یادآور ثبت شده یک پیامک به زمان یک روز(24 ساعت) قبل از زمان&nbsp; یادآور ثبت شده و یک پیامک ساعت 6 صبح روز یادآور ثبت شده با محتوی زیر برای تمامی افرادی که آن پرونده(پرونده ای که شامل یادآور است) در لیست پرونده های آنان قرار دارد ارسال گردد</span></p><p><span style=\"font-family:'Yekan Bakh FaNum Bold', 'Yekan Bakh FaNum Regular', 'Yekan Bakh FaNum', sans-serif;font-weight:700;\"><br></span></p><p><span style=\"font-family:'Yekan Bakh FaNum Bold', 'Yekan Bakh FaNum Regular', 'Yekan Bakh FaNum', sans-serif;font-weight:700;color:rgba(217, 0, 27, 0.996078431372549);\">کاربر گرامی، مطابق ثبت سامانه امور حقوقی، یادآور مربوط به پرونده شماره ۱۲۳۴۵۶۷۸۹۸۰۱۲۳۴۵۶ در تاریخ ۱۴۰۴/۰۶/۱۸ ساعت ۱۰:۰۰ صبح برای شما فعال گردیده است. جهت مشاهده جزئیات، به بخش یادآورها در سامانه امور حقوقی مراجعه فرمایید. واحد امور حقوقی</span></p>",bl="style",bm="baseStyle",bn="627587b6038d43cca051c114ac41ad32",bo="pageAlignment",bp="center",bq="fill",br="fillType",bs="solid",bt="color",bu=0xFFFFFFFF,bv="image",bw="imageAlignment",bx="near",b